/*
    マルQページ仕向け地の取得
*/

    const iomInv = aras.IomInnovator;

    // 選択した仕向け地を取得
    var elements = document.querySelectorAll('input');
    var strDestinations = [];
    for (var i = 0; i < elements.length; i++) {

        var ele = elements[i];
        var eleName = ele.name;
        
        if (ele.type != "checkbox") {
            continue;       // チェックボックス以外は処理対象外
        }
        
        // チェックしてあるチェックボックスを取得
        if (! ele.checked) {
            continue;
        }

        strDestinations.push(ele.id);
    }

    // ダイアログクローズ処理（カンマ[,]区切り文字列生成、0: 仕向け
    parent.dialogArguments.dialog.close(strDestinations);

return;

/*
    イベント設定画面の初期化
*/

    const iomInv = aras.IomInnovator;

    // プロパティに定義されていたスケールの取得
    var destinations = parent.frameElement.dialogArguments.destinations.split(',');

    // h4_destinationから仕向け地を取得
    var lstDestination = iomInv.newItem("List", "get");
    lstDestination.setAttribute("select", "id")
    lstDestination.setProperty("name", "h4_destination");
    lstDestination = lstDestination.apply();

    // リストから仕向け地を取得
    var values = iomInv.newItem("Value", "get");
    values.setAttribute("select", "label,sort_order,value");
    values.setProperty("source_id", lstDestination.getID());
    values = values.apply();

    var targetDistination = [];
    for (var i = 0; i < values.getItemCount(); i++) {
        var wkItem = values.getItemByIndex(i);
        var strDestination = wkItem.getProperty("value");

        // イベントの取得
        targetDistination.push(strDestination);
    }    

    // 仕向け地チェックボックス作成
    addDestinationField(targetDistination, destinations);


/*
    チェックボックス作成メソッド
*/
function addDestinationField(values, selDestination) {

    for (var j = 0; j < Math.ceil(values.length / 8); j++) {
        var mainDiv = document.getElementById('destinationField');
        var subDiv = document.createElement('div');
        
        for (var i =0; i < 8; i++) {
            
            var count = i + (j * 8);
            if (count >= values.length) {
                break;
            }
            
            // チェックボックス作成
            var wkVal = values[count];
            var newField = document.createElement('input');
            newField.type = 'checkbox';
            newField.id = wkVal;
            if (selDestination.includes(wkVal)) {
                newField.checked = true;
            }
            
            // チェックボックスのラベルを作成
            var newLabel = document.createElement('label');
            newLabel.htmlFor = newField.id;
            newLabel.textContent = wkVal + "　　";
            newLabel.style.fontWeight = 'bold';

            subDiv.appendChild(newField);
            subDiv.appendChild(newLabel);
        }
        
        mainDiv.appendChild(subDiv);
        mainDiv.appendChild(document.createElement('br'));

    }
}   

return;
